import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 25 The Cutty Sark","description":"学习 过去完成进行时，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 25 The Cutty Sark","description":"学习 过去完成进行时，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去完成进行时，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 24 A skeleton in the cupboard","link":"/life/english/new-concept/book-3/unit-02/lesson-024"},"next":{"text":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","link":"/life/english/new-concept/book-3/unit-02/lesson-026"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 24 A skeleton in the cupboard","link":"/life/english/new-concept/book-3/unit-02/lesson-024"},"next":{"text":"第三册：培养技能 · Lesson 26 Wanted: a large biscuit tin","link":"/life/english/new-concept/book-3/unit-02/lesson-026"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-025.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-025.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-025.md"};function r(l,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-25-the-cutty-sark" tabindex="-1">第三册：培养技能 · Lesson 25 The Cutty Sark <a class="header-anchor" href="#第三册-培养技能-·-lesson-25-the-cutty-sark" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 25 The Cutty Sark&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕帆船航行和竞争，训练同时交代进度、期限与完成状态。叙述比赛时，不能把“正在航行多久”与“已经完成航程”混为一谈。学习过去完成进行时突出持续过程，并用路线与气候等具体条件解释为什么同一段旅程耗时不同。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>voyage</td><td>/ˈvɔɪɪdʒ/</td><td>n.</td><td>航程</td><td>complete a voyage</td></tr><tr><td>cargo</td><td>/ˈkɑːɡəʊ/</td><td>n.</td><td>货物</td><td>carry cargo</td></tr><tr><td>current</td><td>/ˈkʌrənt/</td><td>n.</td><td>水流</td><td>a strong current</td></tr><tr><td>crew</td><td>/kruː/</td><td>n.</td><td>船员群体</td><td>an experienced crew</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make good progress — 进展顺利</li><li>against the wind — 逆风而行</li></ul><h2 id="语法讲解-过去完成进行时" tabindex="-1">语法讲解：过去完成进行时 <a class="header-anchor" href="#语法讲解-过去完成进行时" aria-label="Permalink to &quot;语法讲解：过去完成进行时&quot;">​</a></h2><p>had been 加动词 ing 表示在过去某个时间点之前持续进行的动作，常与 for、since 连用，强调过程或留下的迹象。过去完成时更容易突出完成结果或数量，例如 had sailed 200 miles；过去完成进行时强调 had been sailing for two days。两种结构有时都可用，但观察焦点不同。know、own 等状态动词通常不采用进行体。持续时长并不自动说明动作在参照点后结束，应由上下文另行交代是否继续。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The crew had been sailing for six hours when the wind finally changed.</p></blockquote><p>风向终于改变时，船员们已经航行了六个小时。</p><p>had been sailing 强调风变前的持续过程；when 从句提供过去参照点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>had been sailed 是被动形式的一部分，不等于 had been sailing；主动进行需要 ing。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 had been rowing 和 had covered 对照朗读，分别重读 hour 与 two kilometres，听出过程和结果的焦点差异。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We had been rowing for an hour when the fog lifted. By then, we had covered only two kilometres. A strong current had slowed us down.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句报告虚构航行进展，区分过程和已完成的距离。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>持续、数量与原因分别用合适结构，避免只凭时间推算进度。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句强调里程还是持续时间？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 持续时间。</p><p><strong>解析：</strong> for six hours 给出时长。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：They had been ___ since dawn.（rowing/rowed）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rowing</p><p><strong>解析：</strong> 完成进行结构使用 ing。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>表达“此前已运送五箱货物”，优先选 had carried 还是 had been carrying？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had carried</p><p><strong>解析：</strong> 完成数量是主要信息。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成进行时。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-024">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-026">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",r]]);export{p as __pageData,b as default};
